style.css:
@-moz-document domain("youtube.com") {
/* 1. Injects your wallpaper behind the page layers */
    html, body, ytd-app {
        background-image: url("https://zenless.tools/images/comic_images_new/s03c01/C30_01_02_01.webp") !important;
        background-size: cover !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-color: transparent !important;
    }

    /* 2. Forces YouTube's deep background variables to go fully transparent */
    html, [dark], html[dark], 
    ytd-app, ytd-masthead, ytd-page-manager, ytd-browse, ytd-search, 
    #page-manager, #columns, #contentContainer, #content-separator,
    ytd-playlist-header-renderer, #background.ytd-playlist-header-renderer {
        background: transparent !important;
        background-color: transparent !important;
        --yt-spec-base-background: transparent !important;
        --yt-spec-general-background-a: transparent !important;
        --yt-spec-general-background-b: transparent !important;
        --yt-spec-general-background-c: transparent !important;
        --yt-spec-static-clear-background: transparent !important;
        --yt-spec-brand-background-solid: transparent !important;
    }

    /* 3. Adds a clean dark-tint behind the text grids so everything stays highly readable */
    #primary, #secondary, ytd-guide-renderer, ytd-mini-guide-renderer {
        background: rgba(0, 0, 0, 0.4) !important;
        padding: 15px;
        border-radius: 12px;
    }
}
